insert into Categorias values ('Ores')
insert into Categorias values ('Herbs')
insert into Categorias values ('Bones')
insert into Categorias values ('Eggs')
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Iron Ore', 1 , 'Ore that can be smelted into metal and used for many different purposes.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Machalite Ore', 1 , 'Ore that''s more difficult to procure than Iron Ore. Produces fine metal.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Dragonite Ore', 1 , 'An ore that yields metal superior to that of Machalite. Invaluable for making durable armor.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Carbalite Ore', 1 , 'Ore obtained from mining outcrops. Still under research, but known to yield highly pure metal.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Fucium Ore', 1 , 'Ore obtained from the Elder''s Recess. A mysterious metal, capable of fusing nearly any two materials together.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Aquacore Ore', 1 , 'A valuable mineral used to create charms. Gives off a vibrant glow that mirrors the ocean.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Spiritcore Ore', 1 , 'A valuable mineral used to create charms. Gives off a warm, sunny glow.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Dreamcore Ore', 1 , 'A valuable mineral used to create charms. Gives off a blazing glow reminiscent of a bonfire.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Dragoncore Ore', 1 , 'A valuable mineral used to create charms. Gives off a mysterious glow that grants the holder sagely wisdom.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Loc Lac Ore', 1 , 'An Old World import. Beautiful, but not suitable for crafting. (Trade-in Item)');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Eltalite Ore', 1 , 'Ore obtained from mining outcrops. This transcendent ore refines into metal even stronger than carbalite.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Shadowcore Ore', 1 , 'A valuable mineral used to create charms. Its shine somehow saps the light away from its surroundings.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Phantomcore Ore', 1 , 'A valuable mineral used to create charms. Its otherworldy shimmering speaks to the power it contains.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Bathycite Ore', 1 , 'Ore from Coral Highlands. Formed by millennia of pressure acting upon the bones of ancient organisms.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Meldspar Ore', 1 , 'Ore often found in the Rotten Vale. Malleable but strong, it is broadly used in creating alloys for crafting.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Fire Herb', 2 , 'A wondrous, flammable plant. Useful for crafting explosives.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Flowfern', 2 , 'This plant''s leaves store a great amount of water. A component for making Water Ammo.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Snow Herb', 2 , 'A plant that radiates ice-cold air. Use in combinations to create freeze ammo.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Sleep Herb', 2 , 'A plant containing sleeping agents. Used to craft tranquilizers.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Ivy', 2 , 'A lightweight and extremely strong plant. Used to make nets for pitfall traps.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Gloamgrass Bud', 2 , 'A plant with healing properties. Combine it with a Godbug to bring out its full potency.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Steel Egg', 3 , 'An egg of glittering steel. Valuable and rare, but of no use to a hunter. (Trade-in Item)');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Silver Egg', 3 , 'An egg of glittering silver. Valuable and rare, but of no use to a hunter. (Trade-in Item)');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Golden Egg', 3 , 'An egg of glittering gold. Super valuable and rare, but of no use to a hunter. (Trade-in Item)');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Sturdy Bone', 4 , 'A bone used as crafting material. Can be found in bonepiles in the Coral Highlands and Rotten Vale.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Quality Bone', 4 , 'A bone used as crafting material. Its ease of use and hardness allow it to be shaped into better gear.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Ancient Bone', 4 , 'A bone used as crafting material. Can be found in bonepiles in the Ancient Forest. Its size evokes a certain primal quality.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Boulder Bone', 4 , 'A bone used as crafting material. Can be found in bonepiles in the Wildspire Waste. Its size evokes a certain primal quality.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Coral Bone', 4 , 'A bone used as crafting material. Can be found in bonepiles in the Coral Highlands. Its size evokes a certain primal quality.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Warped Bone', 4 , 'A bone used as crafting material. Can be found in bonepiles in the Rotten Vale. Its size evokes a certain primal quality.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Brutal Bone', 4 , 'A bone used as crafting material. Can be found in bonepiles in the Elder''s Recess. Its size evokes a certain primal quality.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Dragonbone Relic', 4 , 'A high quality material found in bone piles. The only remains left of a species of dragon now lost to time.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Monster Bone S', 4 , 'A material found in bonepiles. Indispensable for both hunting and daily life.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Monster Bone M', 4 , 'Bone obtained from large monsters. Strong yet flexible, it''s as reliable as steel or wood.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Monster Bone L', 4 , 'Bone obtained from large monsters. Hard to work with due to its size, but vital when crafting larger items.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Monster Bone+', 4 , 'Bone obtained from large monsters. Hard to obtain, but vital for crafting powerful equipment.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Monster Keenbone', 4 , 'Bone obtained from high rank large monsters. It has a razor-sharp tip that retains its strength after forging.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Monster Hardbone', 4 , 'Precious bone obtained from high rank large monsters. Their rarity makes them highly sought after.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Elder Dragon Bone', 4 , 'A bone from an elder dragon. It exudes the great majesty of the beast that bore it.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Anjanath Nosebone', 4 , 'Anjanath material. Obtained by breaking its head. Unusual and difficult to handle.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Anjanath Nosebone+', 4 , 'Rare Anjanath material. Obtained by breaking its head. Unusual and difficult to handle.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Wyvern Bonemass', 4 , 'Radobaan material. Obtained by collecting rare drops. Highly dense, used for many purposes.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Behemoth Bone', 4 , 'Rare Behemoth material. Bone so absurdly strong that it can even knock out legendary heroes.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Dragonbone Artifact', 4 , 'A very rare bone from bonepiles. Evidence of an unknown elder dragon that once ruled the land.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Monster Slogbone', 4 , 'Bone obtained from large master rank monsters. Far heavier than its outward appearance would suggest.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Monster Solidbone', 4 , 'Bone obtained from large master rank monsters. Sturdy enough to withstand even the most ferocious of impacts.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Frozen Bone', 4 , 'A bone found in bonepiles in the Hoarfrost Reach. Tempered by years of the tundra''s unrelenting cold.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Monster Toughbone', 4 , 'Bone obtained from large master rank monsters. It emits a potent aura of near-limitless potential.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Thick Bone', 4 , 'Very rare bone uses as crafting material. While laborious to work, it yields results like no other.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Ancient Cursed Bone', 4 , 'Rare ancient leshen material. A bone entangled in countless magical branches.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Cursed Bone', 4 , 'Rare material. The bone of a creature that fell prey to a leshen''s cunning cruelty.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Heavy Fulgur Anjanath Nosebone', 4 , 'Very rare Fulgur Anjanath material. Obtained by breaking its head. Has a unique composition.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Heavy Anjanath Nosebone', 4 , 'Very rare Anjanath material. Obtained by breaking its head. Used in select gear.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Large Wyvern Bonemass', 4 , 'Very rare Radobaan material. Obtained by collecting rare drops. Highly dense, used for many purposes.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Large Elder Dragon Bone', 4 , 'Material from master rank elder dragons. Equal parts austere and wild, it seems untouched by time.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Elder Dragonvein Bone', 4 , 'Bone obtained from elder dragons in the Guiding Lands. More imposing for having absored earthen energy.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Elder Spiritvein Bone', 4 , 'Bone obtained from tempered monsters in the Guiding Lands. Proof of their status as true masters of the land.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Guiding Forest Dragonbone', 4 , 'Bone obtained in the Guiding Lands'' forest region. Traces of a bygone overlord, drawn by an unknown force.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Guiding Volcanic Dragonbone', 4 , 'Bone obtained in the Guiding Lands'' volcanic region. Traces of a bygone overlord, drawn by an unknown force.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Guiding Coral Dragonbone', 4 , 'Bone obtained in the Guiding Lands'' coral region. Traces of a bygone overlord, drawn by an unknown force.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Guiding Rotted Dragonbone', 4 , 'Bone obtained in the Guiding Lands'' rotted region. Traces of a bygone overlord, drawn by an unknown force.');
