INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Dragonvein Solidbone', 4 , 'Bone obtained from large monsters in the Guiding Lands. Strong as steel after absorbing earthen energy.');
INSERT INTO PuntosInteres (nombre, categoryId, descripcion) VALUES ('Spiritvein Solidbone', 4 , 'Bone obtained from tempered monsters in the Guiding Lands. Drew in earthen energy to slake its endless thrist.');
